from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_score = None
    best_versions = None

    def active_dependencies(row):
        result = []
        for dep in row.get('deps', []):
            if isinstance(dep, dict):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                result.append((
                    dep['name'],
                    dep.get('min', float('-inf')),
                    dep.get('max', float('inf')),
                ))
            else:
                result.append((dep, float('-inf'), float('inf')))
        return result

    def is_acyclic(chosen):
        graph = {
            name: [dep_name for dep_name, _, _ in active_dependencies(row)]
            for name, row in chosen.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph[name]:
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(chosen, pending):
        nonlocal best_score, best_versions

        if not pending:
            if not is_acyclic(chosen):
                return
            score = tuple(
                chosen[name]['version'] if name in chosen else -1
                for name in names
            )
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {
                    name: row['version'] for name, row in chosen.items()
                }
            return

        name, lower, upper = pending[0]
        rest = pending[1:]

        if name not in packages:
            return

        if name in chosen:
            version = chosen[name]['version']
            if lower <= version <= upper:
                search(chosen, rest)
            return

        forbidden = blocked.get(name, [])
        rows = sorted(
            packages[name], key=lambda row: row['version'], reverse=True
        )
        for row in rows:
            version = row['version']
            if not (lower <= version <= upper):
                continue
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            next_chosen = chosen.copy()
            next_chosen[name] = row
            search(next_chosen, rest + active_dependencies(row))

    initial = [
        (name, bounds[0], bounds[1]) for name, bounds in roots.items()
    ]
    search({}, initial)

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
